/**
 * @description Auto-retry planning. A temporary failure (408, 429, 5xx, a callout error or timeout, a send job that
 * stopped) of an outbound event with Auto Retry Max gets Next Retry At = now + Retry After minutes x 2^Auto Retries
 * (15, 30, 60...) while Auto Retries is below the maximum; the message says when. Permanent failures (other 4xx,
 * handler errors, a missing or failing Auth Class) never get one. IntegrationHubAutoRetry sends the due ones again.
 * @group Integration Hub
 */
public with sharing class IntegrationHubRetryPlan {

    /** @description Wait before the first automatic retry when the event's Retry After is blank (minutes). */
    public static final Integer DEFAULT_RETRY_MINUTES = 15;
    /** The longest wait between two automatic retries (minutes): one week. */
    private static final Integer MAX_WAIT_MINUTES = 10080;
    private static final String BY_HAND = ' (temporary: retry from the Monitor or the Transactions tab)';
    private static final String AUTO_SUMMARY = ' (temporary: will retry automatically)';

    /**
     * @description A temporary failure: the transaction is Failed. When the event's Auto Retry Max allows another try,
     * Next Retry At is set and the message says "Will retry automatically at <time> (n of max)."; the summary leaves the
     * time out so the Monitor keeps one group per cause. Otherwise the message says it can be retried by hand.
     * @param t the transaction (Auto_Retries__c read)
     * @param ev its event (Auto_Retry_Max__c and Retry_After_Minutes__c read; may be null)
     * @param message the error
     */
    public static void planRetry(IH_Transaction__c t, IH_Event__c ev, String message) {
        t.Status__c = IntegrationHub.STATUS_FAILED;
        Datetime next = nextRetryAt(t, ev, System.now());
        t.Next_Retry_At__c = next;
        Integer max = maxRetries(ev);
        if (next == null) {
            IntegrationHub.setError(t, message + (max > 0 ? ' (temporary; auto-retry stopped after ' + max + ' of ' + max
                + ': retry from the Monitor or the Transactions tab)' : BY_HAND));
            return;
        }
        t.Error_Message__c = IntegrationHub.clip(message + ' (temporary) Will retry automatically at '
            + next.format('d MMM HH:mm z') + ' (' + (retriesDone(t) + 1) + ' of ' + max + ').', 32768);
        t.Error_Summary__c = IntegrationHub.clip(message, 255 - AUTO_SUMMARY.length()) + AUTO_SUMMARY;
    }

    /**
     * @description Marks transactions Failed after a temporary problem outside the callout (no job could be queued,
     * the send job stopped), planning auto-retry where the event allows it, and saves them. Only transactions still
     * Pending or Retry are changed.
     * @param txnIds the transactions
     * @param reason the error
     */
    public static void failAndSave(List<Id> txnIds, String reason) {
        failAndSave(txnIds, reason, null);
    }

    /**
     * @description As failAndSave(List, String); the transactions in notSent were handed on by the auto-retry sweep but
     * never sent (no job could be queued), so their Auto Retries goes back down: the try is not used up and the next
     * sweep picks them up again.
     * @param txnIds the transactions
     * @param reason the error
     * @param notSent auto-retry transactions whose send was never made (may be null)
     */
    public static void failAndSave(List<Id> txnIds, String reason, Set<Id> notSent) {
        List<IH_Transaction__c> txns = (List<IH_Transaction__c>) IntegrationHubData.query(
            'SELECT Id, Event__c, Auto_Retries__c FROM IH_Transaction__c WHERE Id IN :ids AND Status__c IN :open',
            new Map<String, Object>{ 'ids' => txnIds == null ? new List<Id>() : txnIds,
                'open' => new List<String>{ IntegrationHub.STATUS_PENDING, IntegrationHub.STATUS_RETRY } });
        if (txns.isEmpty()) {
            return;
        }
        Map<Id, IH_Event__c> evs = IntegrationHubOutcome.events(txns);
        for (IH_Transaction__c t : txns) {
            if (notSent != null && notSent.contains(t.Id) && retriesDone(t) > 0) {
                t.Auto_Retries__c = retriesDone(t) - 1;
            }
            planRetry(t, evs.get(t.Event__c), reason);
        }
        IntegrationHubData.updateEach(txns);
    }

    /**
     * @description When the next automatic retry is due: Retry After minutes (15 when blank) times 2 to the power of the
     * automatic retries already made (15, 30, 60...), at most one week.
     * @param t the transaction (Auto_Retries__c read)
     * @param ev its event (may be null)
     * @param now the current time
     * @return the time, or null when auto-retry is off or the maximum is reached
     */
    @TestVisible
    private static Datetime nextRetryAt(IH_Transaction__c t, IH_Event__c ev, Datetime now) {
        Integer done = retriesDone(t);
        if (done >= maxRetries(ev)) {
            return null;
        }
        Integer minutes = ev.Retry_After_Minutes__c == null || ev.Retry_After_Minutes__c < 1
            ? DEFAULT_RETRY_MINUTES : ev.Retry_After_Minutes__c.intValue();
        Integer factor = 1 << Math.min(done, 10);
        return now.addMinutes(Math.min(minutes * factor, MAX_WAIT_MINUTES));
    }

    /**
     * @description The event's Auto Retry Max, 0 when blank (off).
     * @param ev the event (may be null)
     * @return the maximum
     */
    public static Integer maxRetries(IH_Event__c ev) {
        return ev == null || ev.Auto_Retry_Max__c == null ? 0 : Math.max(ev.Auto_Retry_Max__c.intValue(), 0);
    }

    /**
     * @description The transactions whose Auto Retries went up in this update: the sweep raises it when it sets Retry,
     * a manual retry does not. Their sends are logged as Auto Retry.
     * @param txns the updated transactions
     * @param oldMap their previous values (may be null)
     * @return the Ids
     */
    public static Set<Id> raisedIds(List<IH_Transaction__c> txns, Map<Id, IH_Transaction__c> oldMap) {
        Set<Id> raised = new Set<Id>();
        for (IH_Transaction__c t : txns) {
            IH_Transaction__c old = oldMap == null ? null : oldMap.get(t.Id);
            Decimal before = old == null || old.Auto_Retries__c == null ? 0 : old.Auto_Retries__c;
            if (t.Auto_Retries__c != null && t.Auto_Retries__c > before) {
                raised.add(t.Id);
            }
        }
        return raised;
    }

    private static Integer retriesDone(IH_Transaction__c t) {
        return t.Auto_Retries__c == null ? 0 : t.Auto_Retries__c.intValue();
    }
}
